questionvariables.text:
/* ---------- DESIGN BACKWARDS ----------
   Curve  y = x^3 - b x^2 + c   and line  y = x + b  meet where  x^3 - b x^2 - x + (c - b) = 0.
   If the three crossings are x = r1, r2, r3 (whole numbers) then
        r1 + r2 + r3 = b ,   r1 r2 + r1 r3 + r2 r3 = -1 ,   c = b - r1 r2 r3 .
   The middle condition (= -1) is what the line y = x + b forces, so b and c cannot be chosen
   independently: the roots are the free choice, b and c follow.  Pool = [roots, left ends, right ends]:
   8 equation pairs x 2 left ends x 2 right ends = 32 variants; each interval hugs the roots
   (roots span minus 1 or 2 units each side), so the interval depends on the equations. */
pool : [
    [[-5,-1,1],[-7,-6],[2,3]],
    [[-4,-1,1],[-6,-5],[2,3]],
    [[-3,-1,1],[-5,-4],[2,3]],
    [[-2,-1,1],[-4,-3],[2,3]],
    [[-1,1,2],[-3,-2],[3,4]],
    [[-1,1,3],[-3,-2],[4,5]],
    [[-1,1,4],[-3,-2],[5,6]],
    [[-1,1,5],[-3,-2],[6,7]]
];
cfg : rand(pool);
rts : cfg[1];
xlo : rand(cfg[2]);
xhi : rand(cfg[3]);
bb  : rts[1] + rts[2] + rts[3];
cc  : bb - rts[1]*rts[2]*rts[3];

/* the three solutions (the line value equals the cubic value there) */
sx1 : rts[1];  sy1 : sx1 + bb;
sx2 : rts[2];  sy2 : sx2 + bb;
sx3 : rts[3];  sy3 : sx3 + bb;
sol1 : [sx1, sy1];  sol2 : [sx2, sy2];  sol3 : [sx3, sy3];

/* vertical extent: crossings, (0,c), (1,1-b+c), line points, origin, and the second turning point x=2b/3 if it is on the board */
ext   : if is(xlo <= 2*bb/3 and 2*bb/3 <= xhi) then cc - 4*bb^3/27 else cc;
ylist : [sy1, sy2, sy3, cc, 1-bb+cc, bb, 1+bb, 0, ext];
ymin  : floor(lmin(ylist)) - 2;
ymax  : ceiling(lmax(ylist)) + 2;

/* readable equations */
sgnterm(c) := if is(c<0) then sconcat(" - ", string(-c)) else sconcat(" + ", string(c));
qterm(c) := if is(c=1) then " + x^2" else if is(c=-1) then " - x^2" else if is(c<0) then sconcat(" - ", string(-c), "x^2") else sconcat(" + ", string(c), "x^2");
eq1tex : sconcat("y = x^3", qterm(-bb), sgnterm(cc));
eq2tex : sconcat("y = x", sgnterm(bb));

/* model answers: ans1,ans2 = two points on the curve, ans3,ans4 = two points on the line */
ta1 : [0, cc];
ta2 : [1, 1-bb+cc];
ta3 : [0, bb];
ta4 : [1, 1+bb];
ta5 : sol1;  ta6 : sol2;  ta7 : sol3;
swp : reverse(sol1);      /* used only in a question test */

cvals : create_list(k^3 - bb*k^2 + cc, k, [-2,-1,0,1,2,3]);
lvals : create_list(k + bb, k, [-2,-1,0,1,2,3]);

feedbackvariables.text:
u1 : float(ans1[1]); v1 : float(ans1[2]); u2 : float(ans2[1]); v2 : float(ans2[2]);
dd : u1^2 - u2^2;
degen : is(abs(dd) < 0.001);
on1 : is(abs(v1 - (u1^3 - bb*u1^2 + cc)) < 0.2);
on2 : is(abs(v2 - (u2^3 - bb*u2^2 + cc)) < 0.2);
both_on : is(on1 and on2);
beta_s : if degen then 1000 else ((v2-u2^3)-(v1-u1^3))/dd;
gamma_s : if degen then 1000 else (v1-u1^3)+beta_s*u1^2;

d12 : float(sqrt((ans4[1]-ans3[1])^2+(ans4[2]-ans3[2])^2));
dist_ok : is(d12 > 0.5);
on1 : is(abs(float(ans3[2]-(ans3[1]+bb))) < 0.2);
on2 : is(abs(float(ans4[2]-(ans4[1]+bb))) < 0.2);
both_on : is(on1 and on2);
vert : is(abs(float(ans4[1]-ans3[1])) < 0.05);
slope_s : if vert then 1000 else float((ans4[2]-ans3[2])/(ans4[1]-ans3[1]));
icpt_s : if vert then 1000 else float(ans3[2]-slope_s*ans3[1]);

sols : {sol1, sol2, sol3};
nright : cardinality(intersection(setify([ans5, ans6, ans7]), sols));
nswap : cardinality(intersection(setify([reverse(ans5), reverse(ans6), reverse(ans7)]), sols));
